import { readdirSync, readFileSync } from 'node:fs';

/**
 * Grammar table docs for the tutor bot.
 *
 * - `grammarTablesIndex.json` lists every table of the site (key, id, level,
 *   title, hint id); it is generated by scripts/build-grammar-index.mjs.
 * - `grammar-tables/<tableKey>.mjs` is the hand-written doc of one table: what the
 *   bot may highlight (`highlightTargets`) and the CSS selectors, relative to the
 *   table root, that find each target. Tables without a file only have the target
 *   `all` (the whole table).
 *
 * Groups that cut across a table (a declension column, a case row) use CSS classes
 * with the `tt-` prefix on the component's tags (e.g. `tt-genitive`), so several
 * groups can overlap like a grid without changing the component's structure.
 */

const readJson = (name) => JSON.parse(readFileSync(new URL(name, import.meta.url), 'utf8'));

const tablesIndex = readJson('./grammarTablesIndex.json');
// Retired mini-table docs remain archived; the tutor exposes only their current replacements.
const consolidation = readJson('../../../../frontend/src/features/grammar/data/practiceConsolidation.json');

// ':scope' is resolved by the browser to the table root itself.
const WHOLE_TABLE_TARGET = {
  labelRu: 'Вся таблица целиком',
  selectors: [{ selector: ':scope' }],
};

const docsDirectory = new URL('./grammar-tables/', import.meta.url);
const handWrittenDocs = new Map();
for (const file of readdirSync(docsDirectory).filter((name) => name.endsWith('.mjs')).sort()) {
  const { default: doc } = await import(new URL(file, docsDirectory).href);
  handWrittenDocs.set(String(doc.tableKey).toLowerCase(), doc);
}

const docsByLowerKey = new Map();
for (const entry of tablesIndex) {
  const lowerKey = entry.tableKey.toLowerCase();
  const handWritten = handWrittenDocs.get(lowerKey);
  const generic = {
    tableKey: entry.tableKey,
    tableId: entry.tableId,
    level: entry.level,
    hintId: entry.hintId,
    title: entry.title,
    ...(entry.language ? { language: entry.language, href: entry.href } : {}),
    summaryRu: `HTML-таблица «${entry.title}» (уровень ${String(entry.level).toUpperCase()}). Текст таблицы: grammar.table.get_content; подсказка «?»: grammar.table.get_hint.`,
    highlightTargets: {},
  };
  const doc = { ...generic, ...(handWritten || {}) };
  doc.level = entry.level;
  doc.hintId = entry.hintId;
  doc.highlightTargets = { all: WHOLE_TABLE_TARGET, ...(handWritten?.highlightTargets || {}) };
  docsByLowerKey.set(lowerKey, doc);
}
for (const key of handWrittenDocs.keys()) {
  if (!docsByLowerKey.has(key) && !Object.keys(consolidation.retired).some(retired => retired.toLowerCase() === key)) {
    console.warn(`[grammar-tables] doc "${key}" has no entry in grammarTablesIndex.json (run scripts/build-grammar-index.mjs).`);
  }
}

export function listGrammarTableDocs() {
  return [...docsByLowerKey.values()].map((doc) => ({
    tableKey: doc.tableKey,
    tableId: doc.tableId,
    level: doc.level,
    title: doc.title,
    targetCount: Object.keys(doc.highlightTargets).length,
    ...(doc.language ? { language: doc.language, href: doc.href } : {}),
  }));
}

export function getGrammarTableDoc(tableKey) {
  return docsByLowerKey.get(String(tableKey || '').toLowerCase()) || null;
}

const clampMaxChars = (value, fallback, limit) => {
  const number = Number(value);
  if (!Number.isFinite(number) || number <= 0) return fallback;
  return Math.min(limit, Math.max(500, Math.round(number)));
};

/** Ask the browser to read the visible content of a table on the page. */
export function buildGrammarTableReadAction({ table_key, max_chars }) {
  const doc = getGrammarTableDoc(table_key);
  if (!doc) return null;

  return {
    type: 'grammar_table_read',
    emitUiCommand: true,
    tableKey: doc.tableKey,
    tableId: doc.tableId,
    title: doc.title,
    maxChars: clampMaxChars(max_chars, 6000, 12000),
  };
}

/** Ask the browser to load the "?" hint document of a table. */
export function buildGrammarTableHintAction({ table_key, max_chars }) {
  const doc = getGrammarTableDoc(table_key);
  if (!doc) return null;

  return {
    type: 'grammar_table_hint',
    emitUiCommand: true,
    tableKey: doc.tableKey,
    tableId: doc.tableId,
    hintId: doc.hintId,
    title: doc.title,
    maxChars: clampMaxChars(max_chars, 8000, 16000),
  };
}

export function buildGrammarHighlightAction({
  table_key,
  target = 'all',
  duration_ms = 5000,
  color = 'yellow',
}) {
  const doc = getGrammarTableDoc(table_key);
  const highlightTarget = doc?.highlightTargets?.[target];
  if (!doc || !highlightTarget) return null;

  return {
    type: 'grammar_table_highlight',
    emitUiCommand: true,
    tableKey: doc.tableKey,
    tableId: doc.tableId,
    target,
    labelRu: highlightTarget.labelRu,
    durationMs: duration_ms,
    color,
    selectors: highlightTarget.selectors,
  };
}

export function buildGrammarLessonAction({ table_keys = [], steps = [] }) {
  const tableKeys = [...new Set([
    ...table_keys,
    ...steps.map((step) => step?.table_key),
  ].filter(Boolean).map((key) => String(key).toLowerCase()))];

  const lessonSteps = steps.map((step) => {
    const action = buildGrammarHighlightAction(step);
    return {
      ...action,
      startAfterMs: Math.min(60000, Math.max(0, Number(step.start_after_ms || 0))),
    };
  });

  const lastStepEnd = lessonSteps.reduce(
    (max, step) => Math.max(max, step.startAfterMs + step.durationMs),
    0,
  );

  return {
    type: 'grammar_lesson_present',
    emitUiCommand: true,
    tableKeys,
    tableIds: tableKeys.map((key) => getGrammarTableDoc(key).tableId),
    focusOnlyMultiple: tableKeys.length > 1,
    restoreAfterMs: Math.min(75000, Math.max(3500, lastStepEnd + 1200)),
    steps: lessonSteps,
  };
}

export function validateGrammarTableDocParams(params) {
  if (!getGrammarTableDoc(params?.table_key)) {
    return [{
      code: 'unknown_table',
      message: 'Unknown grammar table key. Use grammar.tables.list first.',
      path: 'table_key',
    }];
  }
  return [];
}

export function validateGrammarHighlightParams(params) {
  const doc = getGrammarTableDoc(params?.table_key);
  if (!doc) {
    return [{
      code: 'unknown_table',
      message: 'Unknown grammar table key. Use grammar.tables.list first.',
      path: 'table_key',
    }];
  }
  const target = params?.target || 'all';
  if (!doc.highlightTargets[target]) {
    return [{
      code: 'unknown_highlight_target',
      message: `Unknown highlight target for ${doc.tableKey}. Use grammar.table.get_structure first.`,
      path: 'target',
    }];
  }
  return [];
}

export function validateGrammarLessonParams(params) {
  const tableKeys = Array.isArray(params?.table_keys) ? params.table_keys : [];
  const steps = Array.isArray(params?.steps) ? params.steps : [];
  const errors = [];

  if (steps.length === 0) {
    errors.push({
      code: 'missing_steps',
      message: 'A grammar presentation needs at least one highlight step.',
      path: 'steps',
    });
  }
  if (steps.length > 8) {
    errors.push({
      code: 'too_many_steps',
      message: 'A grammar presentation supports at most 8 highlight steps.',
      path: 'steps',
    });
  }

  const keys = [...new Set([...tableKeys, ...steps.map((step) => step?.table_key)])];
  if (keys.length === 0) {
    errors.push({
      code: 'missing_tables',
      message: 'A grammar presentation needs at least one table key.',
      path: 'table_keys',
    });
  }

  for (const key of keys) {
    if (!getGrammarTableDoc(key)) {
      errors.push({
        code: 'unknown_table',
        message: `Unknown grammar table key: ${key}. Use grammar.tables.list first.`,
        path: 'table_keys',
      });
    }
  }

  steps.forEach((step, index) => {
    const stepErrors = validateGrammarHighlightParams(step || {});
    stepErrors.forEach((error) => {
      errors.push({ ...error, path: `steps.${index}.${error.path}` });
    });
    const startAfterMs = Number(step?.start_after_ms || 0);
    if (!Number.isFinite(startAfterMs) || startAfterMs < 0 || startAfterMs > 60000) {
      errors.push({
        code: 'invalid_start_after_ms',
        message: 'start_after_ms must be a number from 0 to 60000.',
        path: `steps.${index}.start_after_ms`,
      });
    }
  });

  return errors;
}
